<?php
$suiteModule='credits';require __DIR__.'/../common.php';if(!isset($suiteWorkspace))return;
require_once base_app.'classes/Enterprise/CreditService.php';$service=new App\Enterprise\CreditService($conn,$suiteUser);
$credits=$service->credits();$available=array_values(array_filter($credits,static fn($row)=>App\Accounting\Money::compare($row['available'],'0')>0));
$reports=new App\Enterprise\ReportService($conn,$suiteUser);$targets=[];
foreach(['sale','purchase'] as $type)foreach($reports->openDocuments($type,'9999-12-31') as $row)if(App\Accounting\Money::compare($row['outstanding'],'0')>0)$targets[]=array_merge($row,['type'=>$type]);
?>
<div class="suite-heading mb-3"><h4 class="m-0">Customer & Supplier Credits</h4><a class="btn btn-sm btn-outline-secondary" href="<?php echo base_url ?>admin/?page=returns">Returns</a></div>
<h5>Apply Available Return Credit</h5><form class="suite-form suite-filter" data-action="apply_credit"><input type="hidden" name="request_key" value="<?php echo bin2hex(random_bytes(20)) ?>"><div class="suite-grow"><label for="credit-source">Posted Return Credit</label><select class="form-control form-control-sm" id="credit-source" name="return_id" required><option value="">Select available credit</option><?php foreach($available as $row): ?><option value="<?php echo $row['id'] ?>" data-party="<?php echo $row['entity_id'] ?>" data-type="<?php echo $row['invoice_type'] ?>"><?php echo $suiteEscape($row['reference_code'].' / '.$row['party'].' / NPR '.$row['available']) ?></option><?php endforeach ?></select></div><div class="suite-grow"><label for="credit-invoice">Target Invoice / Bill</label><select class="form-control form-control-sm" id="credit-invoice" name="invoice_id" required><option value="">Select invoice</option><?php foreach($targets as $row): ?><option value="<?php echo $row['id'] ?>" data-party="<?php echo $row['party_id'] ?>" data-type="<?php echo $row['type'] ?>"><?php echo $suiteEscape($row['reference_code'].' / '.$row['party'].' / NPR '.$row['outstanding']) ?></option><?php endforeach ?></select></div><div><label for="credit-date">Application Date</label><input class="form-control form-control-sm" type="date" id="credit-date" name="allocation_date" required value="<?php echo date('Y-m-d') ?>"></div><div><label for="credit-amount">Amount (NPR)</label><input class="form-control form-control-sm" type="number" id="credit-amount" name="amount" min="0.01" step="0.01" required></div><div class="suite-grow"><label for="credit-reason">Reason</label><input class="form-control form-control-sm" id="credit-reason" name="reason" maxlength="800" required></div><button class="btn btn-sm btn-primary" type="submit"><i class="fas fa-check mr-1"></i> Apply Credit</button></form>
<p class="suite-report-basis">Available credits are posted returns against paid invoices. Applying credit reallocates settlement within the same party without changing stock, cash, or posted journal amounts.</p>
<h5>Posted Return Credits</h5><?php $suiteTable(array_map(static fn($row)=>['Return'=>$row['reference_code'],'Party'=>$row['party'],'Original Invoice'=>$row['source_invoice'],'Credit'=>$row['credit'],'Allocated'=>$row['allocated'],'Available'=>$row['available']],$credits)); ?>
<h5 class="mt-4">Application History</h5><div class="table-responsive"><table class="table table-sm table-striped"><thead><tr><th>Date</th><th>Return</th><th>Target</th><th>Party</th><th class="text-right">Amount</th><th>Status</th><th></th></tr></thead><tbody><?php foreach($service->allocations() as $row): ?><tr><td><?php echo $row['allocation_date'] ?></td><td><?php echo $suiteEscape($row['credit']) ?></td><td><?php echo $suiteEscape($row['invoice']) ?></td><td><?php echo $suiteEscape($row['party']) ?></td><td class="text-right"><?php echo $row['amount'] ?></td><td><?php echo $row['reversal_id']?'Reversed':($row['reversal_of']?'Reversal':'Applied') ?></td><td><?php if($suiteAdmin&&!$row['reversal_of']&&!$row['reversal_id']): ?><form class="suite-form suite-actions" data-action="reverse_credit"><input type="hidden" name="id" value="<?php echo $row['id'] ?>"><input class="form-control form-control-sm" name="allocation_date" type="date" value="<?php echo date('Y-m-d') ?>" required aria-label="Credit reversal date"><input class="form-control form-control-sm" name="reason" maxlength="800" required placeholder="Reason" aria-label="Credit reversal reason"><button class="btn btn-outline-danger btn-sm" type="submit" title="Reverse credit application" aria-label="Reverse credit application"><i class="fas fa-undo"></i></button></form><?php endif ?></td></tr><?php endforeach ?></tbody></table></div></div>
